using MongoDB.Bson;
using MongoDB.Bson.Serialization.Attributes;

namespace Avalonia_Mapping_Application.DataModels
{
    // GeoCoordinate class to store the name, latitude and longitude of a location
    // Has Bson elements to map the class to the MongoDB collection
    // Has BsonId to set the ID as the primary key, this ID is automatically generated by MongoDB
    public class GeoCoordinate
    {
        [BsonId]
        [BsonRepresentation(BsonType.ObjectId)]
        public string ID { get; set; }

        [BsonElement("Name")]
        public string Name { get; set; }

        [BsonElement("Latitude")]
        public double Latitude { get; set; }

        [BsonElement("Longitude")]
        public double Longitude { get; set; }
    }
}
